<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useAuthSessionStore} from '../../stores/authSession'
import {takeScanHandoff} from '../staff-scan/handoff'
import {cardApi} from './api'
import {useCardText} from './text'
import {displayName,businessDay,cardCode,dateTime} from './format'
import type {Plan,Holding,Customer,CardRequest,QrCode} from './types'
import WalletQrScanner from '../wallet/components/WalletQrScanner.vue'
import WalletQrDisplay from '../wallet/components/WalletQrDisplay.vue'
const props=defineProps<{store:string;plans:Plan[];holdings:Holding[];disabled:boolean;can:(permission:string)=>boolean}>(),emit=defineEmits<{changed:[];error:[message:string]}>(),{t,locale}=useCardText()
const origin=window.location.origin
const auth=useAuthSessionStore()
const search=ref(''),customers=ref<Customer[]>([]),customer=ref(''),card=ref(''),plan=ref(''),source=ref(''),quantity=ref(1),kind=ref('redeem'),request=ref<CardRequest|null>(null),qr=ref<QrCode|null>(null),busy=ref(false),scanMode=ref<'identity'|'authorization'|null>(null)
const customerCards=ref<Holding[]>([]),moreCustomerCards=ref(false)
onMounted(()=>{const owner=auth.user?.accountId??'',value=takeScanHandoff(props.store,owner,'cards'),g=generation;if(value)void run(async()=>{const c=await cardApi(props.store).post<Customer>('/identity',{code:value.code});if(g!==generation||auth.user?.accountId!==owner)return;customer.value=c.id;customers.value=[c]})})
const choices=computed(()=>customer.value?customerCards.value:props.holdings),selected=computed(()=>choices.value.find(h=>h.id===card.value))
let generation=0;watch(()=>props.store,()=>{generation++;customer.value='';card.value='';plan.value='';customers.value=[];request.value=null;qr.value=null;busy.value=false;scanMode.value=null})
async function run(work:()=>Promise<void>){if(busy.value)return;const g=generation;busy.value=true;try{await work();if(g===generation)emit('changed')}catch(e){if(g===generation)emit('error',e instanceof Error?e.message:String(e))}finally{if(g===generation)busy.value=false}}
async function loadCustomer(append=false){const id=customer.value,store=props.store,g=generation;if(!id){customerCards.value=[];moreCustomerCards.value=false;return}try{const suffix=append?`&before=${customerCards.value.at(-1)?.id}`:'';const rows=await cardApi(store).get<Holding[]>(`/holdings?customerId=${encodeURIComponent(id)}${suffix}`);if(g===generation&&id===customer.value){customerCards.value=append?[...customerCards.value,...rows]:rows;moreCustomerCards.value=rows.length===500}}catch(e){if(g===generation)emit('error',String(e))}}
watch([customer,()=>props.holdings],()=>{void loadCustomer()})
async function find(){if(props.disabled)return;await run(async()=>{customers.value=await cardApi(props.store).get<Customer[]>(`/customers?query=${encodeURIComponent(search.value)}`)})}
async function scan(value:string){await run(async()=>{if(scanMode.value==='identity'){const c=await cardApi(props.store).post<Customer>('/identity',{code:value});customer.value=c.id;customers.value=[c];card.value=''}else{const token=cardCode(value,window.location.origin,'CA');if(!token)throw new Error(t('noCard'));await cardApi(props.store).command('/authorized-redeem',{authorization:token},'request.authorized')}scanMode.value=null})}
async function create(){await run(async()=>{const chosen=selected.value;request.value=await cardApi(props.store).command<CardRequest>('/requests',{kind:kind.value,planId:chosen?.planId??plan.value,cardId:chosen?.id??null,quantity:kind.value==='stamp'?1:quantity.value},'request.create');qr.value=await cardApi(props.store).post<QrCode>(`/requests/${request.value.id}/code`)})}
const timer=window.setInterval(async()=>{const r=request.value,store=props.store,g=generation;if(!r||r.status!=='pending'||busy.value)return;try{const updated=await cardApi(store).get<CardRequest>(`/requests/${r.id}`);if(g===generation&&request.value?.id===r.id){request.value=updated;if(updated.status==='completed'){qr.value=null;emit('changed')}}}catch{/* user can refresh after connection recovery */}},3000)
onUnmounted(()=>{generation++;clearInterval(timer)})
</script>
<template><section class="cards-panel cards-operations"><h2>{{t('holdings')}}</h2><form class="cards-actions cards-customer-search" @submit.prevent="find"><input v-model="search" :placeholder="t('search')" :aria-label="t('search')"><button class="primary" :disabled="busy||disabled">{{t('searchAction')}}</button><button type="button" :disabled="busy||disabled" @click="scanMode='identity'">{{t('scan')}} · {{t('customer')}}</button></form><WalletQrScanner v-if="scanMode" :purpose="scanMode==='identity'?'identity':'cardAuthorization'" auto-start :disabled="busy||disabled" @code="scan"/><div class="cards-grid cards-customer-fields"><label>{{t('customer')}}<select v-model="customer" @change="card=''"><option value="">{{t('select')}}</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.displayName}} {{c.phone}}</option></select></label><label>{{t('holdings')}}<select v-model="card"><option value="">{{t('select')}}</option><option v-for="h in choices" :key="h.id" :value="h.id">{{displayName(h.snapshot,locale)}} · {{t(h.kind)}} · {{h.available}}</option></select></label><label>{{t('plans')}}<select v-model="plan"><option value="">{{t('select')}}</option><option v-for="p in plans.filter(p=>p.status==='active')" :key="p.id" :value="p.id">{{displayName(p,locale)}}</option></select></label></div><div class="cards-actions"><button v-if="can('wallet.cards.stamp')" :disabled="!customer||!plan||busy||disabled" @click="run(async()=>{await cardApi(store).command('/enroll',{customerId:customer,planId:plan},'enroll.staff')})">{{t('claim')}}</button></div><button v-if="customer&&moreCustomerCards" :disabled="busy||disabled" @click="loadCustomer(true)">{{t('loadMore')}}</button><div v-if="selected" class="cards-notice"><strong>{{displayName(selected.snapshot.product,locale)}}</strong><p>{{t('remaining')}}: {{selected.remaining??t('unlimited')}} · {{t('today')}}: {{selected.available}}</p><p>{{t('progress')}}: {{selected.progress}} / {{selected.snapshot.stampTarget}} · {{t('expires')}}: {{dateTime(selected.expiresAt,selected.timezone)}}</p></div>
<div v-if="selected?.kind==='stamp'&&can('wallet.cards.stamp')" class="cards-actions"><input v-model="source" :placeholder="t('source')" maxlength="200" style="max-width:300px"><button :disabled="!source||busy||disabled" @click="run(async()=>{await cardApi(store).command('/stamps',{cardId:card,source},'stamp');source=''})">{{t('grant')}}</button></div><div class="cards-grid cards-redemption-fields"><label>{{t('kind')}}<select v-model="kind"><option value="redeem">{{t('redeem')}}</option><option value="stamp">{{t('stamp')}}</option></select></label><label>{{t('quantity')}}<input v-model.number="quantity" type="number" min="1" max="1000000" :disabled="kind==='stamp'"></label></div><div class="cards-actions"><button class="primary" :disabled="busy||disabled||(!card&&!plan)||!can(kind==='stamp'?'wallet.cards.stamp':'wallet.cards.redeem')" @click="create">{{t('merchantCode')}}</button><button v-if="can('wallet.cards.redeem')||can('wallet.cards.stamp')" :disabled="busy||disabled" @click="scanMode='authorization'">{{t('scanCard')}}</button><button v-if="request?.status==='pending'" :disabled="busy" @click="run(async()=>{if(request){request=await cardApi(store).command(`/requests/${request.id}/cancel`,{},'request.cancel');qr=null}})">{{t('cancel')}}</button></div><p class="cards-notice">{{t('dailyHint')}}</p><div v-if="qr&&request" class="cards-qr"><WalletQrDisplay :value="`${origin}/wallet/${store}/cards#card=${qr.code}`" :expires-at="qr.expiresAt"/><a :href="`/wallet/${store}/cards#card=${qr.code}`" target="_blank" rel="noreferrer">{{t('customer')}} · {{t('details')}}</a></div><p v-if="request">{{t('request')}} {{request.id.slice(0,8)}} · {{t(request.status)}}</p></section></template>
